package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Both unchanged API53 methods passed Salesforce Wave101.
func TestRunParentAliasContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAliasDml53.cls"), "@IsTest private class GladeAliasDml53 {\n private static void assertObserved(Object expected,Object actual,String label){\n  if(expected instanceof Map<String,Object>){\n   System.assert(actual instanceof Map<String,Object>,label+': map type');\n   Map<String,Object> want=(Map<String,Object>)expected;Map<String,Object> got=(Map<String,Object>)actual;\n   System.assertEquals(want.keySet(),got.keySet(),label+': exact fields');\n   for(String key:want.keySet())assertObserved(want.get(key),got.get(key),label+'.'+key);\n  }else if(expected instanceof List<Object>){\n   System.assert(actual instanceof List<Object>,label+': list type');\n   List<Object> want=(List<Object>)expected;List<Object> got=(List<Object>)actual;\n   System.assertEquals(want.size(),got.size(),label+': exact size');\n   for(Integer i=0;i<want.size();i++)assertObserved(want[i],got[i],label+'['+i+']');\n  }else{\n   System.assertEquals(expected,actual,label);\n   if(expected instanceof String)System.assert(((String)expected).equals((String)actual),label+': exact text');\n  }\n }\nprivate static void finish(String method,List<Object> rows){String text=JSON.serialize(new Map<String,Object>{'method'=>method,'rows'=>rows,'done'=>true});System.assert(text.length()<2900,method+': complete observation bound');Map<String,String> expectedByMethod=new Map<String,String>{'dynamicParentAlias'=>'{\"done\":true,\"rows\":[{\"count\":1,\"success\":true,\"query\":\"SELECT Id,Name,toLabel(RecordType.Name) RecordTypeLabel FROM GladeAliasRecord53__c WHERE Id=:wanted\",\"phase\":\"query\"},{\"parentName\":{\"message\":\"SObject row was retrieved via SOQL without querying the requested field: RecordType.Name\",\"type\":\"System.SObjectException\"},\"parentAlias\":{\"value\":\"Owned Probe Label\"},\"rootAlias\":{\"message\":\"Invalid field RecordTypeLabel for GladeAliasRecord53__c\",\"type\":\"System.SObjectException\"},\"phase\":\"projection\"},{\"success\":true,\"phase\":\"update\"},{\"count\":1,\"state\":\"Owned\",\"name\":\"after\",\"phase\":\"stored\"}],\"method\":\"dynamicParentAlias\"}','dynamicParentAliasWithRecordTypeId'=>'{\"done\":true,\"rows\":[{\"count\":1,\"success\":true,\"query\":\"SELECT Id,Name,RecordTypeId,toLabel(RecordType.Name) RecordTypeLabel FROM GladeAliasRecord53__c WHERE Id=:wanted\",\"phase\":\"query\"},{\"parentName\":{\"message\":\"SObject row was retrieved via SOQL without querying the requested field: RecordType.Name\",\"type\":\"System.SObjectException\"},\"parentAlias\":{\"value\":\"Owned Probe Label\"},\"rootAlias\":{\"message\":\"Invalid field RecordTypeLabel for GladeAliasRecord53__c\",\"type\":\"System.SObjectException\"},\"phase\":\"projection\"},{\"success\":true,\"phase\":\"update\"},{\"count\":1,\"state\":\"Owned\",\"name\":\"after\",\"phase\":\"stored\"}],\"method\":\"dynamicParentAliasWithRecordTypeId\"}'};System.assert(expectedByMethod.containsKey(method),method+': expected case');assertObserved(JSON.deserializeUntyped(expectedByMethod.get(method)),JSON.deserializeUntyped(text),method);}\n\nprivate static Object read(SObject row,String field){try{return new Map<String,Object>{'value'=>row.get(field)};}catch(Exception e){return new Map<String,Object>{'type'=>e.getTypeName(),'message'=>e.getMessage()};}}\nprivate static Object readParent(SObject row,String relationship,String field){try{return read(row.getSObject(relationship),field);}catch(Exception e){return new Map<String,Object>{'type'=>e.getTypeName(),'message'=>e.getMessage()};}}\nprivate static GladeAliasRecord53__c setup(){RecordType kind=[SELECT Id FROM RecordType WHERE SObjectType='GladeAliasRecord53__c' AND DeveloperName='Owned_Probe'];GladeAliasRecord53__c row=new GladeAliasRecord53__c(Name='before',State__c='Owned',RecordTypeId=kind.Id);insert row;return row;}\nprivate static void updateAndObserve(List<Object> rows,GladeAliasRecord53__c selected){selected.Name='after';Map<String,Object> change=new Map<String,Object>{'phase'=>'update'};try{update selected;change.put('success',true);}catch(DmlException e){change.put('success',false);change.put('type',e.getTypeName());change.put('status',String.valueOf(e.getDmlStatusCode(0)));change.put('message',e.getDmlMessage(0));change.put('fields',e.getDmlFieldNames(0));}rows.add(change);GladeAliasRecord53__c stored=[SELECT Name,State__c FROM GladeAliasRecord53__c WHERE Id=:selected.Id];rows.add(new Map<String,Object>{'phase'=>'stored','name'=>stored.Name,'state'=>stored.State__c,'count'=>[SELECT COUNT() FROM GladeAliasRecord53__c]});}\n\n@IsTest static void dynamicParentAlias(){\n GladeAliasRecord53__c input=setup();Id wanted=input.Id;List<Object> rows=new List<Object>();\n String query='SELECT Id,Name,toLabel(RecordType.Name) RecordTypeLabel FROM GladeAliasRecord53__c WHERE Id=:wanted';GladeAliasRecord53__c selected;\n try{List<SObject> found=Database.query(query);rows.add(new Map<String,Object>{'phase'=>'query','query'=>query,'success'=>true,'count'=>found.size()});selected=(GladeAliasRecord53__c)found[0];}\n catch(Exception e){rows.add(new Map<String,Object>{'phase'=>'query','query'=>query,'success'=>false,'type'=>e.getTypeName(),'message'=>e.getMessage()});}\n if(selected!=null){rows.add(new Map<String,Object>{'phase'=>'projection','rootAlias'=>read(selected,'RecordTypeLabel'),'parentAlias'=>readParent(selected,'RecordType','RecordTypeLabel'),'parentName'=>readParent(selected,'RecordType','Name')});updateAndObserve(rows,selected);}\n finish('dynamicParentAlias',rows);\n}\n@IsTest static void dynamicParentAliasWithRecordTypeId(){\n GladeAliasRecord53__c input=setup();Id wanted=input.Id;List<Object> rows=new List<Object>();\n String query='SELECT Id,Name,RecordTypeId,toLabel(RecordType.Name) RecordTypeLabel FROM GladeAliasRecord53__c WHERE Id=:wanted';GladeAliasRecord53__c selected;\n try{List<SObject> found=Database.query(query);rows.add(new Map<String,Object>{'phase'=>'query','query'=>query,'success'=>true,'count'=>found.size()});selected=(GladeAliasRecord53__c)found[0];}\n catch(Exception e){rows.add(new Map<String,Object>{'phase'=>'query','query'=>query,'success'=>false,'type'=>e.getTypeName(),'message'=>e.getMessage()});}\n if(selected!=null){rows.add(new Map<String,Object>{'phase'=>'projection','rootAlias'=>read(selected,'RecordTypeLabel'),'parentAlias'=>readParent(selected,'RecordType','RecordTypeLabel'),'parentName'=>readParent(selected,'RecordType','Name')});updateAndObserve(rows,selected);}\n finish('dynamicParentAliasWithRecordTypeId',rows);\n}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAliasDml53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeAliasRecord53__c/GladeAliasRecord53__c.object-meta.xml"), "<CustomObject xmlns=\"http://soap.sforce.com/2006/04/metadata\"><deploymentStatus>Deployed</deploymentStatus><label>Glade Alias Record</label><nameField><label>Name</label><type>Text</type></nameField><pluralLabel>Glade Alias Records</pluralLabel><sharingModel>ReadWrite</sharingModel></CustomObject>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeAliasRecord53__c/fields/State__c.field-meta.xml"), "<CustomField xmlns=\"http://soap.sforce.com/2006/04/metadata\"><fullName>State__c</fullName><label>State</label><required>false</required><type>Picklist</type><valueSet><restricted>true</restricted><valueSetDefinition><sorted>false</sorted><value><fullName>Owned</fullName><default>true</default><label>Owned Label</label></value></valueSetDefinition></valueSet></CustomField>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeAliasRecord53__c/recordTypes/Owned_Probe.recordType-meta.xml"), "<RecordType xmlns=\"http://soap.sforce.com/2006/04/metadata\"><fullName>Owned_Probe</fullName><active>true</active><label>Owned Probe Label</label><picklistValues><picklist>State__c</picklist><values><fullName>Owned</fullName><default>true</default></values></picklistValues></RecordType>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"53.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 2 || got.Passed != 2 || got.Failed != 0 || got.Errors != 0 || got.Skipped != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("parent alias contracts: %s", data)
	}
}
